// 백그라운드 Polling 관리 컴포넌트
const BackgroundPollingManager = () => {
  const { setAddress } = useAddress();
  const { showAddressSetSuccessAffordance } = useAddressAffordance();

  useEffect(() => {
    // 백그라운드 polling 성공 콜백 정의
    const handlePollingSuccess = (stayInfo: StayInfo) => {
      if (process.env.NODE_ENV === 'development') {
        console.log('[BackgroundPollingManager] Setting address from polling result:', stayInfo);
      }

      // 별도로 저장된 selectedMethod 확인
      let selectedMethod: 'gps' | 'manual' | 'screenshot' = 'screenshot';
      try {
        const storedMethod = localStorage.getItem('selectedAddressMethod');
        if (storedMethod === 'gps' || storedMethod === 'manual' || storedMethod === 'screenshot') {
          selectedMethod = storedMethod;
        }
      } catch (error) {
        console.error('Error loading selectedAddressMethod:', error);
      }

      // 기존 stay 설정과 동일한 방식으로 주소 정보 설정
      const newAddress = {
        mainAddress: stayInfo.address.address,
        detailAddress: stayInfo.address.detail_address,
        isComplete: true,
        lat: stayInfo.address.lat,
        lng: stayInfo.address.lng,
        addressId: stayInfo.address.id,
        stay: stayInfo, // stay 정보 포함
        selectedMethod: selectedMethod
      };

      setAddress(newAddress);
      
      // 별도로 저장된 selectedMethod 정리
      try {
        localStorage.removeItem('selectedAddressMethod');
      } catch (error) {
        console.error('Error removing selectedAddressMethod:', error);
      }
      
      // 주소 설정 성공 어포던스 트리거
      setTimeout(() => {
        showAddressSetSuccessAffordance();
      }, 500); // 주소 설정 후 약간의 지연을 두고 어포던스 표시
      
      if (process.env.NODE_ENV === 'development') {
        console.log('[BackgroundPollingManager] Address updated successfully');
      }
    };

    // 글로벌 성공 콜백 등록
    pollingService.setGlobalSuccessCallback(handlePollingSuccess);

    // 컴포넌트 언마운트 시 polling 정리
    return () => {
      if (pollingService.isCurrentlyPolling()) {
        pollingService.stopPolling();
      }
      // 콜백 정리
      pollingService.setGlobalSuccessCallback(() => {});
    };
  }, [setAddress, showAddressSetSuccessAffordance]);

  return null; // UI를 렌더링하지 않음
};

