// 채널톡 관리 컴포넌트 - 홈 페이지에서만 활성화
const ChannelTalkManager = () => {
  const location = useLocation();

  // DOM에서 채널톡 버튼 요소들을 모두 찾아 표시/숨김 처리하는 함수
  const toggleChannelTalkButton = (show: boolean) => {
    // 커스텀 버튼 처리
    const customButton = document.getElementById("custom-channel-button");
    if (customButton) {
      customButton.style.display = show ? "flex" : "none";
    }

    // 채널톡의 기본 버튼 처리 (클래스로 찾기)
    const channelButtons = document.querySelectorAll('[class*="channel-"]');
    channelButtons.forEach((button) => {
      const element = button as HTMLElement;
      if (
        element.tagName === "BUTTON" ||
        (element.tagName === "DIV" &&
          (element.style.position === "fixed" ||
            element.getAttribute("class")?.includes("launcher")))
      ) {
        // z-index 조정을 통해 다른 UI 요소와 겹치지 않도록 함
        if (element.style.zIndex) {
          element.style.zIndex = "998"; // 낮은 z-index 사용
        }
        element.style.display = show ? "" : "none";
      }
    });

    // iframe 처리 (채널톡은 종종 iframe을 사용)
    const iframes = document.querySelectorAll("iframe");
    iframes.forEach((iframe) => {
      if (iframe.src.includes("channel.io")) {
        // z-index 조정
        const parent = iframe.parentElement;
        if (parent && parent instanceof HTMLElement) {
          parent.style.zIndex = "998";
        }
        iframe.style.display = show ? "" : "none";
      }
    });
  };

  useEffect(() => {
    // 현재 언어 설정으로 채널톡 초기화
    const currentLang = getCurrentLanguage();
    bootChannelTalk(
      {
        language: currentLang,
      },
      true
    ); // 강제 초기화 플래그 true로 설정

    // 현재 페이지 이름 설정
    setChannelTalkPage(location.pathname || "Home");

    // 약간의 지연 후 DOM에서 버튼 표시
    setTimeout(() => {
      toggleChannelTalkButton(true);
    }, 500);

    // 컴포넌트 언마운트 시 정리 작업
    return () => {
      // 특별한 정리 작업은 필요 없음
    };
  }, [location.pathname, location.hash]);

  // 초기 로드 시 한 번만 실행
  useEffect(() => {
    // GitHub Pages에서는 초기 로드 시 추가 부트스트랩 시도
    if (window.location.hostname.includes("github.io")) {
      // 약간의 지연 후 채널톡 초기화 다시 시도
      setTimeout(() => {
        const currentLang = getCurrentLanguage();
        bootChannelTalk(
          {
            language: currentLang,
          },
          true
        );
      }, 1500);
    }
  }, []);

  // 언어 변경 감지 및 처리
  useEffect(() => {
    const handleLanguageChange = (event: Event) => {
      const customEvent = event as CustomEvent<{ language: SupportedLanguage }>;
      const newLang = customEvent.detail.language;

      // 홈 페이지에서만 언어 변경 적용
      if (window.ChannelIO) {
        shutdownChannelTalk();

        // 약간의 지연 후 새 언어로 재시작
        setTimeout(() => {
          bootChannelTalk(
            {
              language: newLang,
            },
            true
          );
        }, 300);
      }
    };

    // 언어 변경 이벤트 리스너 등록
    window.addEventListener(
      LANGUAGE_CHANGE_EVENT,
      handleLanguageChange as EventListener
    );

    return () => {
      window.removeEventListener(
        LANGUAGE_CHANGE_EVENT,
        handleLanguageChange as EventListener
      );
    };
  }, []);

  return null;
};

// 글로벌 URL 파라미터 처리 컴포넌트
const GlobalUrlParameterHandler = () => {
  const location = useLocation();
  const { setAddress } = useAddress();
  const hasLoadedRef = useRef<string | null>(null);

  useEffect(() => {
    const handleUrlParameters = async () => {
      // 해시 라우터에서는 쿼리 파라미터가 location.search와 hash 부분에 모두 있을 수 있음
      let searchParams = "";

      // location.search에서 파라미터 확인
      if (location.search) {
        searchParams = location.search;
      }

      // 해시 부분에서도 쿼리 파라미터 확인 (예: #/guides/1?stayId=...)
      const hashParts = window.location.hash.split("?");
      if (hashParts.length > 1) {
        searchParams = "?" + hashParts[1];
      }

      const urlParams = new URLSearchParams(searchParams);
      const stayIdFromQuery = urlParams.get("stayId");
      const promotionUserIdFromQuery = urlParams.get("promotionUserId");
      const langFromQuery = urlParams.get("lang");

      let hasParamsToStore = false;
      let shouldLoadStay = false;
      let stayIdToLoad = null;

      if (stayIdFromQuery) {
        // 이미 이 stayId로 로드했다면 스킵
        if (hasLoadedRef.current !== stayIdFromQuery) {
          // localStorage에 저장
          localStorage.setItem("pendingStayId", stayIdFromQuery);
          hasLoadedRef.current = stayIdFromQuery;
          shouldLoadStay = true;
          stayIdToLoad = stayIdFromQuery;
        }
        urlParams.delete("stayId");
        hasParamsToStore = true;
      }

      if (promotionUserIdFromQuery) {
        // localStorage에 promotion user ID 저장
        localStorage.setItem("promotionUserId", promotionUserIdFromQuery);
        urlParams.delete("promotionUserId");
        hasParamsToStore = true;
      }

      if (langFromQuery) {
        // 언어 설정 변경
        const supportedLanguages = ["en", "ko", "ja", "zh-CN", "zh-TW"];
        if (supportedLanguages.includes(langFromQuery)) {
          setLanguage(langFromQuery as SupportedLanguage);
        }
        urlParams.delete("lang");
        hasParamsToStore = true;
      }

      if (hasParamsToStore) {
        // URL에서 파라미터들 제거
        const cleanSearch = urlParams.toString();
        const cleanUrl = cleanSearch ? `?${cleanSearch}` : "";

        // 해시 라우터의 경우 해시 부분을 업데이트
        if (hashParts.length > 1) {
          const newHash = hashParts[0] + cleanUrl;
          window.history.replaceState(
            {},
            "",
            window.location.pathname + window.location.search + newHash
          );
        } else {
          // 일반적인 경우
          const newUrl = `${location.pathname}${cleanUrl}${location.hash}`;
          window.history.replaceState({}, "", newUrl);
        }
      }

      // localStorage에서 pendingStayId 확인 (URL 파라미터에서 처리되지 않은 경우)
      if (!shouldLoadStay) {
        const pendingStayId = localStorage.getItem("pendingStayId");
        if (pendingStayId && hasLoadedRef.current !== pendingStayId) {
          // 온보딩 상태 확인 - 온보딩 중이면 useStayPreloader에서 처리하므로 여기서는 처리하지 않음
          const hasSeenOnboarding = localStorage.getItem("hasSeenOnboarding");
          
          if (hasSeenOnboarding) {
            // 온보딩이 완료된 경우에만 여기서 처리
            shouldLoadStay = true;
            stayIdToLoad = pendingStayId;
            hasLoadedRef.current = pendingStayId;
            // localStorage에서 제거 (한 번만 사용)
            localStorage.removeItem("pendingStayId");
            console.log("📍 GlobalUrlParameterHandler: pendingStayId 처리 (온보딩 완료)", pendingStayId);
          } else {
            // 온보딩 중이면 useStayPreloader에서 처리하므로 여기서는 처리하지 않음
            console.log("📍 GlobalUrlParameterHandler: 온보딩 중이므로 pendingStayId 처리 건너뛰기", pendingStayId);
          }
        }
      }

      // stayId가 있으면 stay 정보 로드
      if (shouldLoadStay && stayIdToLoad) {
        try {
          console.log("📍 GlobalUrlParameterHandler: Stay 정보 로드 시작", stayIdToLoad);
          const stayInfo = await getStayInfo(stayIdToLoad);

          // 주소 정보를 AddressContext에 설정
          const newAddress = {
            mainAddress: stayInfo.address.address,
            detailAddress: stayInfo.address.detail_address,
            isComplete: true,
            lat: stayInfo.address.lat,
            lng: stayInfo.address.lng,
            addressId: stayInfo.address.id,
            stay: stayInfo  // stay 정보 추가
          };

          setAddress(newAddress);
          console.log("✅ GlobalUrlParameterHandler: 주소 설정 완료", stayInfo.address.address);
        } catch (error) {
          console.error("❌ GlobalUrlParameterHandler: Stay 정보 로드 실패:", error);
        }
      }
    };

    handleUrlParameters();
  }, [location.search, location.pathname, location.hash, setAddress]);

  return null;
};

// 글로벌 서비스 상태 관리 컴포넌트
const GlobalServiceStatusManager = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const [isChecking, setIsChecking] = useState(false);
  const lastCheckTimeRef = useRef<number>(0);
  const MINIMUM_CHECK_INTERVAL = 30 * 1000; // 30초 최소 간격

  useEffect(() => {
    const checkServiceStatus = async () => {
      // 이미 메인터넌스 페이지에 있으면 체크하지 않음
      if (location.pathname === "/maintenance") {
        return;
      }

      // 중복 체크 방지
      if (isChecking) {
        return;
      }

      // 최소 간격 체크
      const now = Date.now();
      if (now - lastCheckTimeRef.current < MINIMUM_CHECK_INTERVAL) {
        return;
      }

      setIsChecking(true);
      lastCheckTimeRef.current = now;

      try {
        // 캐시된 상태 확인 (OperationTimeService의 캐시 활용)
        const status = await getOperationStatus();

        // 에러 상태이면 메인터넌스 페이지로 이동
        if (status.isError) {
          navigate("/maintenance", { replace: true });
        }
      } catch (error) {
        console.error("Service status check failed:", error);
        navigate("/maintenance", { replace: true });
      } finally {
        setIsChecking(false);
      }
    };

    // 페이지 변경 시마다 서비스 상태 확인 (하지만 캐시와 간격 제한 적용)
    checkServiceStatus();
  }, [
    location.pathname,
    location.search,
    navigate,
    isChecking,
    MINIMUM_CHECK_INTERVAL,
  ]);

  return null;
};

