// 홈 화면 컴포넌트
const HomeComponent = () => {
  const { address } = useAddress();
  const [promotionData, setPromotionData] = useState<PromotionPopupData | null>(
    null
  );
  const [showPromotionPopup, setShowPromotionPopup] = useState(false);
  const navigate = useNavigate();

  // Stay 정보 백그라운드 로드 (최종 안전장치)
  useStayPreloader();
  
  // 홈페이지 데이터 백그라운드 프리로딩 (최종 안전장치)
  useHomeDataPreloader();

  // 온보딩 완료 여부 체크
  useEffect(() => {
    const hasSeenOnboarding = localStorage.getItem("hasSeenOnboarding");

    // 온보딩을 본 적이 없다면 온보딩 페이지로 리다이렉트
    if (!hasSeenOnboarding) {
      navigate("/onboarding", { replace: true });
      return;
    }
  }, [navigate]);

  // 프로모션 데이터 로드
  const loadPromotionData = useCallback(async () => {
    try {
      const currentLang = getCurrentLanguage();
      const addressId = address?.addressId;
      const promotionUserId = localStorage.getItem("promotionUserId");

      // addressId가 없으면 프로모션 데이터 로드를 건너뜀
      if (!addressId) {
        console.debug("Address ID not available, skipping promotion data load");
        return;
      }

      // 프로모션 코드 조회 (addressId 포함)
      const promotionData = await getPromotionCode(
        currentLang,
        addressId,
        promotionUserId || undefined
      );

      if (
        promotionData &&
        promotionData.isActive &&
        !promotionData.isApplied &&
        canShowPromotionPopup(
          promotionData.startDate,
          promotionData.endDate,
          promotionData.code
        )
      ) {
        const popupData = transformPromotionData(promotionData);
        setPromotionData(popupData);
        setShowPromotionPopup(true);
      }
    } catch (error) {
      console.error("Error loading promotion data:", error);
    }
  }, [address?.addressId]);

  // 초기 프로모션 데이터 로드
  useEffect(() => {
    loadPromotionData();
  }, [loadPromotionData]);

  // 주소 변경 시 프로모션 데이터 다시 로드
  useEffect(() => {
    if (address?.addressId) {
      loadPromotionData();
    }
  }, [address?.addressId, loadPromotionData]);

  // 언어 변경 시 프로모션 데이터 다시 로드
  useEffect(() => {
    const handleLanguageChange = (event: Event) => {
      const customEvent = event as CustomEvent<{ language: SupportedLanguage }>;
      console.debug(
        "Language changed in HomeComponent, reloading promotion data:",
        customEvent.detail.language
      );

      // 현재 팝업이 열려있다면 닫기
      setShowPromotionPopup(false);
      setPromotionData(null);

      // 새 언어로 프로모션 데이터 다시 로드
      setTimeout(() => {
        loadPromotionData();
      }, 500);
    };

    // 언어 변경 이벤트 리스너 등록
    window.addEventListener(
      LANGUAGE_CHANGE_EVENT,
      handleLanguageChange as EventListener
    );

    return () => {
      // 이벤트 리스너 제거
      window.removeEventListener(
        LANGUAGE_CHANGE_EVENT,
        handleLanguageChange as EventListener
      );
    };
  }, [loadPromotionData]);

  const handleClosePromotionPopup = () => {
    setShowPromotionPopup(false);
  };

  return (
    <>
      <Header />
      <main className="md-background pb-16">
        <LocationBanner />
        <div className="md-surface">
          <GuideBanner />
        </div>
        <div className="md-surface">
          <CategorySection />
        </div>
        <div className="md-surface">
          <CurationSection />
        </div>
        <div className="md-surface mt-2">
          <Footer />
        </div>
      </main>
      <BottomBanner />
      <NavigationBar />

      {/* 프로모션 팝업 */}
      {promotionData && (
        <PromotionPopup
          promotion={promotionData}
          isVisible={showPromotionPopup}
          onClose={handleClosePromotionPopup}
        />
      )}
    </>
  );
};

// 앱 수준의 이벤트 핸들러 컴포넌트
const AppEventHandler = () => {
  useEffect(() => {
    // 언어 변경 이벤트 발생 시, 해당 언어의 API 캐시를 무효화
    const handleLanguageChange = (event: Event) => {
      const customEvent = event as CustomEvent<{
        language: SupportedLanguage;
        timestamp: number;
      }>;
      const newLang = customEvent.detail.language;

      // 이전 언어의 캐시 무효화
      invalidateLanguageCache(newLang);
    };

    // 언어 변경 이벤트 리스너 등록
    window.addEventListener(
      LANGUAGE_CHANGE_EVENT,
      handleLanguageChange as EventListener
    );

    return () => {
      // 이벤트 리스너 제거
      window.removeEventListener(
        LANGUAGE_CHANGE_EVENT,
        handleLanguageChange as EventListener
      );
    };
  }, []);

  return null;
};

