import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useTranslation } from '../hooks/useTranslation';
import { trackEvent } from '../services/AnalyticsService';
import { getCurrentLanguage } from '../config/languageConfig';
import { useStayPreloader } from '../hooks/useStayPreloader';
import { useHomeDataPreloader } from '../hooks/useHomeDataPreloader';

const OnboardingPage: React.FC = () => {
  const navigate = useNavigate();
  const { t } = useTranslation();
  const [isLoaded, setIsLoaded] = useState(false);
  
  // Stay 정보 백그라운드 로드 (UI에 영향 없음)
  useStayPreloader();
  
  // 홈페이지 데이터 백그라운드 프리로딩 (UI에 영향 없음)
  useHomeDataPreloader();
  
  // 터치 이벤트 상태
  const [touchStart, setTouchStart] = useState<number | null>(null);
  const [touchEnd, setTouchEnd] = useState<number | null>(null);

  // 이미 온보딩을 완료한 사용자가 접근했을 때 홈으로 리다이렉트
  useEffect(() => {
    const hasSeenOnboarding = localStorage.getItem('hasSeenOnboarding');
    if (hasSeenOnboarding) {
      navigate('/', { replace: true });
    }
  }, [navigate]);

  // 페이지 로드 GA 이벤트
  useEffect(() => {
    trackEvent('onboarding_page_1_view', {
      page_number: 1,
      page_title: 'Onboarding Welcome',
      user_language: getCurrentLanguage(),
      timestamp: Date.now()
    });
  }, []);

  // 애니메이션 트리거
  useEffect(() => {
    const timer = setTimeout(() => {
      setIsLoaded(true);
    }, 50);
    
    return () => clearTimeout(timer);
  }, []);

  const markOnboardingComplete = () => {
    // 온보딩 완료 상태를 localStorage에 저장
    localStorage.setItem('hasSeenOnboarding', 'true');
  };

  // 개발자 도구: 온보딩 상태 초기화 (브라우저 콘솔에서 사용)
  // localStorage.removeItem('hasSeenOnboarding'); window.location.reload();
  
  // 개발자 도구: 언어 설정 초기화 (브라우저 콘솔에서 사용) 
  // localStorage.removeItem('app_language'); localStorage.removeItem('last_detected_language'); window.location.reload();

  const handleNext = () => {
    // 두 번째 온보딩 페이지로 이동
    navigate('/onboarding2');
  };

  const handleSkip = () => {
    // GA 이벤트 추적
    trackEvent('onboarding_skip_clicked', {
      page_number: 1,
      page_title: 'Onboarding Welcome',
      user_language: getCurrentLanguage(),
      timestamp: Date.now()
    });
    
    markOnboardingComplete();
    // 온보딩을 건너뛰고 홈으로 이동
    navigate('/');
  };

  // 터치 시작
  const handleTouchStart = (e: React.TouchEvent) => {
    setTouchEnd(null);
    setTouchStart(e.targetTouches[0].clientX);
  };

  // 터치 이동
  const handleTouchMove = (e: React.TouchEvent) => {
    setTouchEnd(e.targetTouches[0].clientX);
    
    // 수평 스와이프인 경우 기본 스크롤 동작 방지
    if (touchStart !== null) {
      const currentTouch = e.targetTouches[0].clientX;
      const distance = Math.abs(touchStart - currentTouch);
      
      // 수평 이동이 10px 이상이면 기본 동작 방지
      if (distance > 10) {
        e.preventDefault();
      }
    }
  };

  // 터치 종료
  const handleTouchEnd = (e: React.TouchEvent) => {
    if (!touchStart || !touchEnd) {
      return;
    }
    
    const distance = touchStart - touchEnd;
    const isLeftSwipe = distance > 50; // 왼쪽으로 스와이프 (다음 페이지)

    if (isLeftSwipe) {
      handleNext();
      e.preventDefault();
    }
    // 첫 번째 페이지이므로 오른쪽 스와이프는 무시
    
    // 터치 상태 초기화
    setTouchStart(null);
    setTouchEnd(null);
  };

  return (
    <div 
      className="min-h-[100dvh] bg-white flex flex-col touch-pan-y"
      style={{ touchAction: 'pan-y pinch-zoom' }}
      onTouchStart={handleTouchStart}
      onTouchMove={handleTouchMove}
      onTouchEnd={handleTouchEnd}
    >
      {/* 상단 헤더 영역 - 일관된 레이아웃 */}
      <div className={`flex justify-end items-center p-4 sm:p-6 pt-3 transition-opacity duration-500 will-change-transform ${isLoaded ? 'opacity-100' : 'opacity-0'}`}>
        {/* Skip 버튼 - 터치 영역 확보 */}
        <button
          onClick={handleSkip}
          className="text-gray-500 text-sm font-medium min-w-[60px] min-h-[44px] flex items-center justify-center -mr-3"
        >
          {t('onboarding.skip')}
        </button>
      </div>

      {/* 메인 콘텐츠 */}
      <div className="flex-1 flex flex-col items-center justify-center px-6 sm:px-8">
        {/* 서비스 로고 */}
        <div className={`mb-4 sm:mb-8 transition-opacity duration-600 will-change-transform ${isLoaded ? 'opacity-100' : 'opacity-0'}`}>
          <img
            src="https://recipeee-api.s3.ap-northeast-2.amazonaws.com/delivereee/logo.png"
            alt="KOREA ORDER Logo"
            className="w-48 sm:w-60 h-auto max-w-full"
            loading="eager"
            onError={(e) => {
              console.error('로고 이미지 로드 실패');
              // 로고 로드 실패 시 대체 텍스트 표시 가능
            }}
          />
        </div>

        {/* 슬로건 */}
        <div className={`text-center space-y-3 sm:space-y-4 max-w-sm transition-opacity duration-700 will-change-transform ${isLoaded ? 'opacity-100 delay-200' : 'opacity-0'}`}>
          <h1 className="text-lg sm:text-xl font-bold text-gray-900 leading-relaxed">
            {t('onboarding.welcome.title')}
          </h1>
          <p className="text-sm sm:text-sm text-gray-600 leading-relaxed">
            {t('onboarding.welcome.subtitle1')}
            <br />
            {t('onboarding.welcome.subtitle2')}
          </p>
        </div>
      </div>

      {/* 하단 네비게이션 영역 */}
      <div className={`p-4 sm:p-6 space-y-6 sm:space-y-10 transition-opacity duration-800 will-change-transform ${isLoaded ? 'opacity-100 delay-300' : 'opacity-0'}`}>
        {/* 페이지 인디케이터 */}
        <div className="flex justify-center items-center space-x-2">
          <div className="w-6 h-3 bg-red-500 rounded-full"></div>
          <div className="w-3 h-3 bg-gray-300 rounded-full"></div>
          <div className="w-3 h-3 bg-gray-300 rounded-full"></div>
          <div className="w-3 h-3 bg-gray-300 rounded-full"></div>
        </div>
        
        {/* Next 버튼 */}
        <button
          onClick={handleNext}
          className="w-full bg-red-500 text-white py-2 px-6 rounded-lg font-semibold text-lg transition-colors duration-200 hover:bg-red-600 active:bg-red-700"
        >
          {t('onboarding.next')} →
        </button>
      </div>
    </div>
  );
};

export default OnboardingPage; 