import React, { useEffect } from 'react';
import ReactDOM from 'react-dom/client';
import './index.css';
import App from './App';
import reportWebVitals from './reportWebVitals';
import { setLanguage, SupportedLanguage } from './config/languageConfig';

// Wrapper component to handle redirect from 404.html and non-hash URLs
const AppWithRedirectHandler: React.FC = () => {
  // After the app mounts, check if there's a redirect path stored in sessionStorage
  useEffect(() => {
    const redirectPath = sessionStorage.getItem('redirectPath');
    
    if (redirectPath) {
      // Clear the redirect path from sessionStorage
      sessionStorage.removeItem('redirectPath');
      
      // Get the base path for the GitHub Pages site
      const basePath = '/home';
      
      // If we have a redirect path, navigate to that route inside the app
      // This needs to be done after a slight delay to allow the router to initialize
      setTimeout(() => {
        window.history.pushState({}, '', basePath + redirectPath);
        // Dispatch a popstate event so the router can detect the change
        window.dispatchEvent(new PopStateEvent('popstate', { state: {} }));
      }, 100);
    }
  }, []);

  // Handle non-hash URLs by redirecting to hash URLs
  useEffect(() => {
    const currentPath = window.location.pathname;
    const currentHash = window.location.hash;
    const currentSearch = window.location.search;
    
    // URL 쿼리 파라미터에서 stayId, promotionUserId, lang 확인
    const urlParams = new URLSearchParams(currentSearch);
    const stayIdFromQuery = urlParams.get('stayId');
    const promotionUserIdFromQuery = urlParams.get('promotionUserId');
    const langFromQuery = urlParams.get('lang');
    
    let hasParamsToStore = false;
    
    if (stayIdFromQuery) {
      // localStorage에 stay ID 저장
      localStorage.setItem('pendingStayId', stayIdFromQuery);
      urlParams.delete('stayId');
      hasParamsToStore = true;
    }
    
    if (promotionUserIdFromQuery) {
      // localStorage에 promotion user ID 저장
      localStorage.setItem('promotionUserId', promotionUserIdFromQuery);
      urlParams.delete('promotionUserId');
      hasParamsToStore = true;
    }
    
    if (langFromQuery) {
      // 언어 설정 변경
      const supportedLanguages = ['en', 'ko', 'ja', 'zh-CN', 'zh-TW'];
      if (supportedLanguages.includes(langFromQuery)) {
        setLanguage(langFromQuery as SupportedLanguage);
      }
      urlParams.delete('lang');
      hasParamsToStore = true;
    }
    
    // Special handling for stay URLs first
    // URL 끝의 #, /, #/ 등을 제거하여 깔끔하게 처리
    const cleanPath = currentPath.replace(/[/#]+$/, '');
    
    // 온보딩 관련 해시인지 확인하는 함수
    const isOnboardingHash = (hash: string): boolean => {
      return hash === '' || 
             hash === '/' || 
             hash === '#' ||
             hash === '#/' ||
             hash.startsWith('#/onboarding') ||
             hash.startsWith('/onboarding');
    };
    
    const stayMatch = cleanPath.match(/\/home\/stays\/([^/#?]+)$/);
    if (stayMatch) {
      const stayId = stayMatch[1];
      
      // localStorage에 stay ID 저장 (온보딩 상태와 관계없이)
      localStorage.setItem('pendingStayId', stayId);
      
      // 온보딩이 필요한지 확인
      const hasSeenOnboarding = localStorage.getItem('hasSeenOnboarding');
      
      if (!hasSeenOnboarding) {
        // 온보딩이 필요한 경우 온보딩 해시로 리다이렉트
        window.location.href = `${window.location.origin}/home/#/onboarding`;
        return;
      } else {
        // 온보딩이 완료된 경우 깔끔한 홈 URL로 리다이렉트
        const targetHash = (!currentHash || isOnboardingHash(currentHash)) ? '#' : currentHash;
        window.location.href = `${window.location.origin}/home/${targetHash}`;
        return;
      }
    }

    // Special handling for new domain stay URLs
    // URL 끝에 #, /, #/ 등이 붙는 경우를 먼저 제거하고 처리
    const newDomainStayMatch = cleanPath.match(/^\/stays\/([^/#?]+)$/);
    if (newDomainStayMatch) {
      const stayId = newDomainStayMatch[1];
      
      try {
        // localStorage에 stay ID 저장 (온보딩 상태와 관계없이)
        localStorage.setItem('pendingStayId', stayId);
        
        // 저장 확인 (모바일 디버깅용)
        const savedStayId = localStorage.getItem('pendingStayId');
        console.log('Stay ID 저장 확인:', { stayId, savedStayId, match: stayId === savedStayId, cleanPath });
        
        // 온보딩이 필요한지 확인
        const hasSeenOnboarding = localStorage.getItem('hasSeenOnboarding');
        
        if (!hasSeenOnboarding) {
          // 온보딩이 필요한 경우 온보딩으로 리다이렉트
          window.location.href = `${window.location.origin}/home/#/onboarding`;
          return;
        } else {
          // 온보딩이 완료된 경우 홈으로 리다이렉트
          window.location.href = `${window.location.origin}/home/#`;
          return;
        }
      } catch (error) {
        console.error('Error handling new domain stay URL:', error);
        // 에러 발생 시 기본 홈으로 리다이렉트
        window.location.href = `${window.location.origin}/home/#`;
        return;
      }
    }
    
    // If we're not on the base path and there's no hash, redirect to hash URL
    if (currentPath !== '/' && currentPath !== '/home' && !currentHash) {
      // Extract the path after /home if it exists
      let routePath = currentPath;
      if (currentPath.startsWith('/home')) {
        routePath = currentPath.substring(5); // Remove '/home' prefix
      }
      
      // 파라미터들을 제거한 깔끔한 URL로 리다이렉트
      const cleanSearch = urlParams.toString();
      const cleanUrl = cleanSearch ? `?${cleanSearch}` : '';
      
      // Redirect to hash URL
      window.location.href = `${window.location.origin}${window.location.pathname.includes('/home') ? '/home' : ''}${cleanUrl}/#${routePath}`;
      return;
    }
    
    // 파라미터만 있는 경우 (경로는 이미 올바른 경우)
    if (hasParamsToStore) {
      // 파라미터들을 제거한 깔끔한 URL로 리다이렉트
      const cleanSearch = urlParams.toString();
      const cleanUrl = cleanSearch ? `?${cleanSearch}` : '';
      
      if (currentHash) {
        // 해시 URL이 있는 경우
        window.location.href = `${window.location.origin}${currentPath}${cleanUrl}${currentHash}`;
      } else {
        // 해시 URL이 없는 경우 해시 URL로 리다이렉트
        window.location.href = `${window.location.origin}${window.location.pathname.includes('/home') ? '/home' : ''}${cleanUrl}/#`;
      }
      return;
    }
  }, []);

  return <App />;
};

const root = ReactDOM.createRoot(
  document.getElementById('root') as HTMLElement
);
root.render(
  <React.StrictMode>
    <AppWithRedirectHandler />
  </React.StrictMode>
);

// If you want to start measuring performance in your app, pass a function
// to log results (for example: reportWebVitals(console.log))
// or send to an analytics endpoint. Learn more: https://bit.ly/CRA-vitals
reportWebVitals();
